/* From Uiverse.io by SanjanaSogimatt - Tags: neumorphism, skeuomorphism, minimalist, gradient, button, hover, glow, radio, animated, futuristic-radio-buttons */
.__UIV_SCOPE__ .radio-input {
  box-shadow: -10px -15px 15px rgba(255, 255, 255, 0.5),
    10px 10px 25px rgba(70, 70, 70, 0.5);
  margin: auto;
  height: 80px;
  width: 300px;
  display: flex;
  align-items: center;
  justify-content: space-around;
  position: absolute;
  border-radius: 50px;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: white;
}

.__UIV_SCOPE__ .radio-input input[type="radio"] {
  display: none;
}

.__UIV_SCOPE__ .label {
  font-size: .9rem;
  font-weight: 600;
  font-family: 'poppins',sans-serif;
  padding: 18px 15px;
  border-radius: 35px;
  transition: 0.5s;
  cursor: pointer;
  color: black;
}

.__UIV_SCOPE__ .radio-input input[type="radio"]:checked + label {
  box-shadow: 10px 10px 15px rgba(0, 0, 0, 0.151),
    10px 10px 15px rgba(0, 0, 0, 0.218);
  background: linear-gradient(45deg,#cf6efb,#4f29cd);
  color: white;
  transform: translateY(-4px);
}

.__UIV_SCOPE__ .radio-input input[type="radio"]:hover:not(:checked)+ label {
  box-shadow: inset 10px 10px 15px rgba(0, 0, 0, 0.151),
    inset 10px 10px 15px rgba(0, 0, 0, 0.218);
}
